  SELECT 'MODEL_OUTPUT' ASSIGNMENT_REASON_CODE, 'خروجی مدل یا امتیازدهی' NAME_FA, 'Model Output' NAME_EN, 30 SORT_ORDER FROM DUAL
  UNION ALL
  SELECT 'REGULATORY_REQUIREMENT' ASSIGNMENT_REASON_CODE, 'الزام مقرراتی' NAME_FA, 'Regulatory Requirement' NAME_EN, 40 SORT_ORDER FROM DUAL
